async function (fieldId, values) {
  if (["Sold"].includes(fieldId)) {
    const val = values[fieldId];
    COMMON.text = val ? '' + val : '';
    if (val === null) return true;
    const flag = (val || val === 0) && val <= 10000 && val >= 0;
    if (!flag) {
      showAlert('Amount must bigger then 0 and small then 10000');
    }
    return flag;
  }
  if (["startDate"].includes(fieldId)) {
    const val = values[fieldId];
    const flag = !val || val > '2025-05-10';
    if (!flag) {
      showAlert('startDate must after 2025-05-10');
    }
    return flag;
  }
  if (["startTime"].includes(fieldId)) {
    const val = values[fieldId];
    const flag = !val || val > '08:00:00';
    if (!flag) {
      showAlert('startDate must after 08:00:00');
    }
    return flag;
  }
  if (["fullStartTime"].includes(fieldId)) {
    const val = values[fieldId];
    const flag = !val || val > '2025-05-10 20:00:00';
    if (!flag) {
      showAlert('startDate must after 2025-05-10 20:00:00');
    }
    return flag;
  }
  if (["Country"].includes(fieldId)) {}
  const flag = values[fieldId]?.length < 8;
  if (!flag) {
    showAlert('error');
  }
  return flag;
}

