function (ps_type, ps_data, ps_fields, po_format) {
  let value, where;
  let setSort = TEST.s_sort(Object.keys(ps_data));
  for (const key of setSort) {
    const field = ps_fields.find(item => item.sysao03 === key);
    const data = TEST.set_processed_data(field, ps_data[key], po_format);
    if (["where", "set"].includes(ps_type)) {
      where = where === undefined ? [key, data].join(" = ") : [where, [key, data].join(" = ")].join(" AND ");
      if (ps_type === "set") {
        value = value === undefined ? [key, data].join(" = ") : [value, [key, data].join(" = ")].join(" , ");
      }
    } else if (ps_type === "value") {
      where = where === undefined ? key : [where, key].join(" , ");
      value = value === undefined ? data : [value, data].join(" , ");
    }
  }
  return {
    key: where,
    value: value
  };
}

