export default {
	s_sort(arr, compareFn) {
		if (typeof compareFn !== "function") {
			compareFn = (a, b) => {
				if (typeof a === "string" && typeof b === "string") {
					return a.localeCompare(b); //字符串按字母顺序排序
				} else if (typeof a === "number" && typeof b === "number") {
					return a - b; //数字按大小排序
				}
				return 0;
			};
		}
		function quickSort(array) {
			if (array.length <= 1) {
				return array;
			}
			const pivot = array[0];
			const left = [];
			const right = [];
			for (let i = 1; i < array.length; i++) {
				if (compareFn(array[i], pivot) < 0) {
					left.push(array[i]);
				} else {
					right.push(array[i]);
				}
			}
			return [...quickSort(left), pivot, ...quickSort(right)];
		}
		return quickSort(arr);
	},
	set_processed_data(obj, field, po_format) {
		try {
			const sysbc04 = obj.sysbc04;
			const sysbc08 = obj.sysbc08;
			if (["varchar", "varchar2"].includes(sysbc04) && sysbc08 === "Y") {
				if ([true, "true", "Y", "y"].includes(field)) {
					return "'Y'";
				} else if ([false, "false", "N", "n"].includes(field)) {
					return "'N'";
				} else {
					return "null";
				}
			} else if (
				["varchar", "varchar2", "text"].includes(sysbc04) &&
				sysbc08 === "N"
			) {
				return field === null ||
					field === undefined ||
					field === "undefined" ||
					field === "" ||
					field === ""
					? "null"
				: "'" + field + "'";
			} else if (sysbc04 === "time") {
				return field === null ||
					field === undefined ||
					field === "undefined" ||
					field === "" ||
					field === ""
					? "null"
				: `TO_TIMESTAMP('${field}','${po_format["time"]}')`;
			} else if (sysbc04 === "date") {
				return field === null ||
					field === undefined ||
					field === "undefined" ||
					field === "" ||
					field === ""
					? "null"
				: `TO_TIMESTAMP('${field}','${po_format["date"]}')`;
			} else if (sysbc04 === "timestamp") {
				return field === null ||
					field === undefined ||
					field === "undefined" ||
					field === "" ||
					field === ""
					? "null"
				: `TO_TIMESTAMP('${field}','${po_format["datetime"]}')`;
