		for (const key of setSort) {
			const field = ps_fields.find((item) => item.sysao03 === key);
			const data = this.set_processed_data(field, ps_data[key], po_format);
			if (["where", "set"].includes(ps_type)) {
				where =
					where === undefined
					? [key, data].join(" = ")
				: [where, [key, data].join(" = ")].join(" AND ");
				if (ps_type === "set") {
